package me.tbsten.collector.internal

/** Marks API that only code generated by the Collector compiler plugin may call. */
@RequiresOptIn(level = RequiresOptIn.Level.ERROR, message = "Only for code generated by the Collector compiler plugin.")
@Retention(AnnotationRetention.BINARY)
public annotation class InternalCollectorApi

/** Called from code generated by the Collector compiler plugin. */
@InternalCollectorApi
public object CollectorInternals {
    /** A sequence that calls each factory only when it reaches that element. */
    public fun <T> sequenceOfFactories(vararg factories: () -> T): Sequence<T> =
        factories.asSequence().map { it() }
}
